"use client"

import { useState, useEffect } from "react"
import { useNavigate } from "react-router-dom"
import { Calendar, AlertCircle, Loader2 } from 'lucide-react'
import { motion } from "framer-motion"
import Layout from "./Layout"

export default function AddReport() {
  const [startDate, setStartDate] = useState("")
  const [endDate, setEndDate] = useState("")
  const [reason, setReason] = useState("")
  const [error, setError] = useState(null)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const navigate = useNavigate()

  useEffect(() => {
    const token = localStorage.getItem("token")
    if (!token) {
      navigate("/") // Redirect to login if no token
    }
  }, [navigate])

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError(null)
    setIsSubmitting(true)

    // Validation
    if (!startDate || !endDate || !reason) {
      setError("Tous les champs (date de début, date de fin, raison) sont requis.")
      setIsSubmitting(false)
      return
    }

    if (new Date(startDate) > new Date(endDate)) {
      setError("La date de début ne peut pas être postérieure à la date de fin.")
      setIsSubmitting(false)
      return
    }

    const token = localStorage.getItem("token")
    const role = localStorage.getItem("role")
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/api/absence`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
          Role: role,
        },
        body: JSON.stringify({
          startDate,
          endDate,
          reason,
        }),
      })

      const data = await response.json()
      if (response.ok) {
        navigate("/intern/absences-history")
      } else {
        setError(data.message || "Échec de l'envoi du rapport.")
      }
    } catch (error) {
      setError("Erreur réseau. Veuillez réessayer.")
      console.error("Network error:", error)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4 sm:py-6">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50"
        >
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 sm:p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-xl sm:text-2xl font-bold tracking-tight">Ajouter un rapport</h1>
                <p className="text-white/80 mt-1 text-sm">Soumettez un nouveau rapport d'absence</p>
              </div>
            </div>
          </div>
          <div className="p-4 sm:p-6">
            <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6">
              <div className="space-y-2">
                <label
                  htmlFor="startDate"
                  className="block text-xs font-medium text-[#00717F] uppercase tracking-wider"
                >
                  Date de début <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <input
                    type="date"
                    id="startDate"
                    className="w-full px-4 py-2 sm:py-3 border border-[#C8A45D/30] rounded-md bg-white text-gray-900 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all pl-10"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    required
                    disabled={isSubmitting}
                  />
                  <Calendar className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F] absolute left-3 top-1/2 transform -translate-y-1/2" />
                </div>
              </div>
              <div className="space-y-2">
                <label
                  htmlFor="endDate"
                  className="block text-xs font-medium text-[#00717F] uppercase tracking-wider"
                >
                  Date de fin <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <input
                    type="date"
                    id="endDate"
                    className="w-full px-4 py-2 sm:py-3 border border-[#C8A45D/30] rounded-md bg-white text-gray-900 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all pl-10"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    required
                    disabled={isSubmitting}
                  />
                  <Calendar className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F] absolute left-3 top-1/2 transform -translate-y-1/2" />
                </div>
              </div>
              <div className="space-y-2">
                <label
                  htmlFor="reason"
                  className="block text-xs font-medium text-[#00717F] uppercase tracking-wider"
                >
                  Raison <span className="text-red-500">*</span>
                </label>
                <textarea
                  id="reason"
                  className="w-full px-4 py-2 sm:py-3 border border-[#C8A45D/30] rounded-xl bg-white text-gray-900 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all resize-y"
                  rows="4"
                  placeholder="Entrez la raison de votre absence..."
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  required
                  disabled={isSubmitting}
                />
              </div>
              {error && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3 }}
                  className="p-3 sm:p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm"
                >
                  <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
                  <p className="text-xs sm:text-sm text-red-700">{error}</p>
                </motion.div>
              )}
              <motion.button
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-[#00717F] text-white py-2 sm:py-3 px-4 rounded-md shadow-sm hover:bg-[#00717F] transition-colors duration-300 flex items-center justify-center gap-2 text-xs sm:text-sm font-medium disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {isSubmitting && <Loader2 className="h-3 w-3 sm:h-4 sm:w-4 animate-spin" />}
                {isSubmitting ? "Envoi en cours..." : "Soumettre le rapport"}
              </motion.button>
            </form>
          </div>
        </motion.div>
      </div>
    </Layout>
  )
}
